import{_ as e,a as d,o as a,a6 as o}from"./chunks/framework.CJDy2q7X.js";const h=JSON.parse('{"title":"Product Images — Update","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-catalog-product-image-update","title":"Update a Product Image","description":"Edit the alt text and the position of an already-uploaded image.","query":"mutation UpdateImage($input: updateAdminCatalogProductImageInput!) {\\n  updateAdminCatalogProductImage(input: $input) {\\n    adminCatalogProductImage {\\n      _id\\n      productId\\n      path\\n      position\\n      url\\n      altText\\n      success\\n      message\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"id\\": \\"/api/admin/catalog/products/12/images/47\\",\\n    \\"productId\\": 12,\\n    \\"imageId\\": 47,\\n    \\"altText\\": \\"Blue running shoe, side view\\",\\n    \\"position\\": 2\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"updateAdminCatalogProductImage\\": {\\n      \\"adminCatalogProductImage\\": {\\n        \\"_id\\": 47,\\n        \\"productId\\": 12,\\n        \\"path\\": \\"product/12/abc123.webp\\",\\n        \\"position\\": 2,\\n        \\"url\\": \\"/storage/product/12/abc123.webp\\",\\n        \\"altText\\": \\"Blue running shoe, side view\\",\\n        \\"success\\": true,\\n        \\"message\\": \\"Product image updated successfully.\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/catalog/products/images-update.md","filePath":"api/graphql-api/admin/catalog/products/images-update.md","lastUpdated":1789385991000}'),r={name:"api/graphql-api/admin/catalog/products/images-update.md"};function i(n,t,c,s,l,p){return a(),d("div",null,t[0]||(t[0]=[o('<h1 id="product-images-—-update" tabindex="-1">Product Images — Update <a class="header-anchor" href="#product-images-—-update" aria-label="Permalink to &quot;Product Images — Update&quot;">​</a></h1><p>Equivalent to <a href="/api/rest-api/admin/catalog/products/images-update.html"><code>PUT /api/admin/catalog/products/{productId}/images/{id}</code></a>.</p><p>Edits what is stored alongside an uploaded image: its alt text and its position. The file itself is fixed once uploaded — to replace the picture, upload a new one (REST only) and delete this one.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th></tr></thead><tbody><tr><td><code>updateAdminCatalogProductImage</code></td><td>Mutation</td></tr></tbody></table><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID!</code></td><td>yes</td><td>The image&#39;s IRI, e.g. <code>/api/admin/catalog/products/12/images/47</code>.</td></tr><tr><td><code>productId</code></td><td><code>Int</code></td><td>no</td><td>Parent product id. Taken from the image when omitted.</td></tr><tr><td><code>imageId</code></td><td><code>Int</code></td><td>no</td><td>Image id. Taken from <code>id</code> when omitted.</td></tr><tr><td><code>altText</code></td><td><code>String</code></td><td>no</td><td>Description of the image, stored for every locale the request covers. Send an empty string to clear it.</td></tr><tr><td><code>position</code></td><td><code>Int</code></td><td>no</td><td>Sort position within the product&#39;s gallery.</td></tr></tbody></table><p>At least one of <code>altText</code> and <code>position</code> is required — a mutation carrying neither is rejected.</p><h2 id="alt-text-and-locales" tabindex="-1">Alt text and locales <a class="header-anchor" href="#alt-text-and-locales" aria-label="Permalink to &quot;Alt text and locales&quot;">​</a></h2><p>Alt text is translated: it is written for every locale the request covers, and read back for the locale the request is made in. The storefront returns it as <code>altText</code> on the product&#39;s images, and falls back to the product name where an image has none, so an image is never rendered without a description.</p><h2 id="position-and-gallery-order" tabindex="-1">Position and gallery order <a class="header-anchor" href="#position-and-gallery-order" aria-label="Permalink to &quot;Position and gallery order&quot;">​</a></h2><p>Images resolve in position order, so this is what decides which picture is the product&#39;s main image — the lowest position wins, and that is the one the listing and the product card show. To rearrange several at once, use <a href="/api/graphql-api/admin/catalog/products/images-reorder.html">reorder</a> instead.</p><h2 id="response-fields" tabindex="-1">Response fields <a class="header-anchor" href="#response-fields" aria-label="Permalink to &quot;Response fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>_id</code></td><td><code>Int</code></td><td>Image id.</td></tr><tr><td><code>productId</code></td><td><code>Int</code></td><td>Parent product id.</td></tr><tr><td><code>path</code></td><td><code>String</code></td><td>Storage-relative file path.</td></tr><tr><td><code>position</code></td><td><code>Int</code></td><td>Sort position.</td></tr><tr><td><code>url</code></td><td><code>String</code></td><td>Public URL.</td></tr><tr><td><code>altText</code></td><td><code>String</code></td><td>Alt text stored for the current locale, or <code>null</code>.</td></tr><tr><td><code>success</code></td><td><code>Boolean</code></td><td>Whether the edit was applied.</td></tr><tr><td><code>message</code></td><td><code>String</code></td><td>Human-readable result message.</td></tr></tbody></table>',14)]))}const m=e(r,[["render",i]]);export{h as __pageData,m as default};
